insert into hosts (id, display_name, tagline, bio, avatar_url, response_time, hosting_since, average_rating) values
  ('h_maissa', 'Maissa', 'Superhost · Djerba & Ezzahra', 'I look after two design-forward homes — a courtyard villa in Djerba and a terrace loft in Ezzahra — each one personally renovated and photographed to give guests an honest sense of the space before they book. Both are prepared, cleaned and checked by the same team, so what you see in the listing is what you walk into. If something is not right, I answer within the hour.', '/images/hosts/maissa.svg', 'within an hour', 2022, 4.9);
insert into listings (id, host_id, slug, title, location, region, style_tag, status, price_per_night, currency, hero_photo_url, gallery_urls, spin_photo_urls, video_tour_url, lat, lng, summary, description, bedrooms, beds, bathrooms, max_guests, amenities, rating, review_count) values
  ('l_djerba_villa', 'h_maissa', 'djerba-villa', 'Djerba Villa', 'Houmt Souk, Djerba', 'Djerba', 'whitewashed-courtyard-calm', 'featured'::listing_status, 320, 'TND', '/images/listings/djerba-villa/hero.svg', ARRAY['/images/listings/djerba-villa/g1.svg', '/images/listings/djerba-villa/g2.svg', '/images/listings/djerba-villa/g3.svg', '/images/listings/djerba-villa/g4.svg', '/images/listings/djerba-villa/g5.svg', '/images/listings/djerba-villa/g6.svg']::text[], ARRAY['/images/spin/djerba-villa/00.svg', '/images/spin/djerba-villa/01.svg', '/images/spin/djerba-villa/02.svg', '/images/spin/djerba-villa/03.svg', '/images/spin/djerba-villa/04.svg', '/images/spin/djerba-villa/05.svg', '/images/spin/djerba-villa/06.svg', '/images/spin/djerba-villa/07.svg', '/images/spin/djerba-villa/08.svg', '/images/spin/djerba-villa/09.svg', '/images/spin/djerba-villa/10.svg', '/images/spin/djerba-villa/11.svg', '/images/spin/djerba-villa/12.svg', '/images/spin/djerba-villa/13.svg', '/images/spin/djerba-villa/14.svg', '/images/spin/djerba-villa/15.svg', '/images/spin/djerba-villa/16.svg', '/images/spin/djerba-villa/17.svg', '/images/spin/djerba-villa/18.svg', '/images/spin/djerba-villa/19.svg', '/images/spin/djerba-villa/20.svg', '/images/spin/djerba-villa/21.svg', '/images/spin/djerba-villa/22.svg', '/images/spin/djerba-villa/23.svg']::text[], null, 33.8756, 10.8578, 'A whitewashed courtyard house four streets back from the fish market, rebuilt around its original vaulted rooms. Breakfast happens under the fig tree.', ARRAY['Djerba Villa is a traditional courtyard house reworked room by room over two years. The vaulted ceilings and thick lime-washed walls are original; the plumbing, wiring and kitchen are not. It keeps the house cool through July and August without leaning on air conditioning.', 'The central courtyard is the heart of the house. Breakfast happens there under the fig tree, and it stays shaded until mid-afternoon. Three bedrooms open off it, each with its own door to the courtyard rather than an internal corridor.', 'The fish market, the Sunday souk and the ferry terminal are all inside a fifteen-minute walk. The nearest swimmable beach at Sidi Mahrez is a nine-minute drive north.']::text[], 3, 4, 2, 6, '[{"label":"Shaded central courtyard","icon":"garden"},{"label":"Roof terrace","icon":"terrace"},{"label":"Air conditioning in every room","icon":"ac"},{"label":"Fibre Wi-Fi, 200 Mbps","icon":"wifi"},{"label":"Full kitchen with gas range","icon":"kitchen"},{"label":"Washing machine","icon":"washer"},{"label":"Free street parking","icon":"parking"},{"label":"Desk and monitor","icon":"workspace"}]'::jsonb, 4.9, 128),
  ('l_ezzahra_apartment_loft', 'h_maissa', 'ezzahra-apartment-loft', 'Ezzahra Apartment Loft', 'Ezzahra, Ben Arous', 'Tunis', 'terrace-loft-panoramic', 'active'::listing_status, 280, 'TND', '/images/listings/ezzahra-apartment-loft/hero.svg', ARRAY['/images/listings/ezzahra-apartment-loft/g1.svg', '/images/listings/ezzahra-apartment-loft/g2.svg', '/images/listings/ezzahra-apartment-loft/g3.svg', '/images/listings/ezzahra-apartment-loft/g4.svg', '/images/listings/ezzahra-apartment-loft/g5.svg', '/images/listings/ezzahra-apartment-loft/g6.svg']::text[], ARRAY['/images/spin/ezzahra-apartment-loft/00.svg', '/images/spin/ezzahra-apartment-loft/01.svg', '/images/spin/ezzahra-apartment-loft/02.svg', '/images/spin/ezzahra-apartment-loft/03.svg', '/images/spin/ezzahra-apartment-loft/04.svg', '/images/spin/ezzahra-apartment-loft/05.svg', '/images/spin/ezzahra-apartment-loft/06.svg', '/images/spin/ezzahra-apartment-loft/07.svg', '/images/spin/ezzahra-apartment-loft/08.svg', '/images/spin/ezzahra-apartment-loft/09.svg', '/images/spin/ezzahra-apartment-loft/10.svg', '/images/spin/ezzahra-apartment-loft/11.svg', '/images/spin/ezzahra-apartment-loft/12.svg', '/images/spin/ezzahra-apartment-loft/13.svg', '/images/spin/ezzahra-apartment-loft/14.svg', '/images/spin/ezzahra-apartment-loft/15.svg', '/images/spin/ezzahra-apartment-loft/16.svg', '/images/spin/ezzahra-apartment-loft/17.svg', '/images/spin/ezzahra-apartment-loft/18.svg', '/images/spin/ezzahra-apartment-loft/19.svg', '/images/spin/ezzahra-apartment-loft/20.svg', '/images/spin/ezzahra-apartment-loft/21.svg', '/images/spin/ezzahra-apartment-loft/22.svg', '/images/spin/ezzahra-apartment-loft/23.svg']::text[], null, 36.7419, 10.3103, 'A top-floor loft on the quiet side of the hill, with a private terrace facing north-east across the Gulf of Tunis toward Carthage.', ARRAY['The loft occupies the whole top floor of a small 1970s building on the quiet side of the Ezzahra hill. It was stripped back to the shell in 2023: one open living space under the original concrete beams, a galley kitchen along the north wall, and the bedroom behind a full-height sliding partition.', 'The terrace is the reason to book it. It runs the length of the flat, faces north-east down the gulf toward Carthage, and gets direct sun from first light until about two in the afternoon — then falls into shade for the rest of the day, which in July is the point.', 'It is twenty minutes down the coast road into central Tunis and ten to the Carthage headland. The Ezzahra beach and the TGM station are both a seven-minute walk downhill.']::text[], 1, 2, 1, 3, '[{"label":"Private terrace over the gulf","icon":"terrace"},{"label":"Sea view from every room","icon":"sea"},{"label":"Fibre Wi-Fi, 100 Mbps","icon":"wifi"},{"label":"Split-unit air conditioning","icon":"ac"},{"label":"Galley kitchen","icon":"kitchen"},{"label":"Washing machine","icon":"washer"},{"label":"Residents parking","icon":"parking"},{"label":"Dedicated workspace","icon":"workspace"}]'::jsonb, 4.85, 41);
